	/**
	 * Collects the distinct predicates of one statement set in unsigned ascending order. The predicate is the leading
	 * key field of the {@code po}-prefixed index, so after recording a predicate the scan jumps straight to the first
	 * key of the next predicate (a loose index / skip scan via {@link RecordIterator#seekForward}) instead of walking
	 * every triple that shares it — turning an O(triples) scan into O(distinct predicates) cursor seeks. When the
	 * iterator cannot seek (an implementation without native support), the scan falls back to plain stepping with the
	 * same duplicate-skipping guard, so the result is identical either way.
	 */
	private long[] distinctPredicates(boolean explicit) throws IOException {
		long[] buffer = new long[16];
		int size = 0;
		LmdbPrefixRunPlan prefixPlan = tripleStore.prefixRunPlan(PREDICATE_PREFIX_FIELDS, -1, -1, -1, -1);
		if (prefixPlan != null) {
			// Pass 0 only needs one row per predicate. A predicate-leading index lets LMDB skip the remaining rows in
			// each predicate run instead of decoding every statement in the incoming stream.
			cursorSeeks++;
			try (LmdbPrefixRunCursor it = tripleStore.getPrefixRuns(txn, prefixPlan, -1, -1, -1, -1, explicit, false)) {
				while (it.next()) {
					cursorRowsScanned++;
					cursorRowsMatched++;
					long predicate = it.quad()[TripleIndex.PRED_IDX];
					if (size > 0 && Long.compareUnsigned(buffer[size - 1], predicate) > 0) {
						throw new IOException("predicate stream is not unsigned ascending");
					}
					if (size == buffer.length) {
						buffer = java.util.Arrays.copyOf(buffer, buffer.length * 2);
					}
					buffer[size++] = predicate;
				}
			}
		} else {
			try (RecordIterator it = incomingIterator(explicit)) {
				long[] batch = quadBatch();
				long last = 0;
				boolean any = false;
				int rows;
				while ((rows = it.fill(batch, BATCH_ROWS)) > 0) {
					cursorRowsScanned += rows;
					cursorRowsMatched += rows;
					for (int row = 0; row < rows; row++) {
						long predicate = batch[row * 4 + TripleIndex.PRED_IDX];
						if (!any || predicate != last) {
							if (any && Long.compareUnsigned(last, predicate) > 0) {
								throw new IOException("predicate stream is not unsigned ascending");
							}
							if (size == buffer.length) {
								buffer = java.util.Arrays.copyOf(buffer, buffer.length * 2);
							}
							buffer[size++] = predicate;
							last = predicate;
							any = true;
						}
					}
				}
			}
		}
		return Arrays.copyOf(buffer, size);
	}

	@Override
	public void scanContexts(ContextConsumer consumer) throws IOException {
		try (LmdbContextIdIterator it = tripleStore.getContexts(txn)) {
			long[] record;
			while ((record = it.next()) != null) {
				if (record[0] != 0) {
					consumer.context(record[0]);
				}
			}
		}
	}

